 "content": "def transform(grid):
    out = [row[:] for row in grid]
    marker_row = next(i for i, row in enumerate(grid) if any(v in (2, 8) for v in row))
    # Each marker draws an upward ray of three cells total: two 1s and
    # its own color at the far endpoint. If near the top, truncate naturally.
    for c, color in enumerate(grid[marker_row]):
        if color in (2, 8):
            for distance in range(1, 4):
                r = marker_row - distance
                if r < 0:
                    break
                out[r][c] = color if distance == min(3, marker_row) else 1
    return out
